"""Read-only seller/profile-scoped Ads historical diagnostics."""
class AdsDiagnosticsService:
    def __init__(self,repository):self._repository=repository
    def get(self,seller_id,marketplace_id,profile_id):
        if not profile_id:return {"seller_id":seller_id,"marketplace_id":marketplace_id,"profile_id":None,"performance_row_count":0,"ingestion_run_count":0,"successful_run_count":0,"failed_run_count":0,"last_ingestion_at":None,"last_successful_ingestion_at":None,"latest_run_status":None,"latest_run_rows_saved":0,"latest_run_rows_failed":0,"earliest_data_date":None,"latest_data_date":None}
        total=self._repository.count_performance_rows(seller_id,marketplace_id,profile_id);runs=self._repository.count_ingestion_runs(seller_id,marketplace_id,profile_id);successful=self._repository.count_ingestion_runs(seller_id,marketplace_id,profile_id,True);latest=self._repository.get_latest_ingestion_run(seller_id,marketplace_id,profile_id);latest_success=self._repository.get_latest_successful_ingestion_run(seller_id,marketplace_id,profile_id);dates=self._repository.get_data_date_range(seller_id,marketplace_id,profile_id)
        return {"seller_id":seller_id,"marketplace_id":marketplace_id,"profile_id":str(profile_id),"performance_row_count":total,"ingestion_run_count":runs,"successful_run_count":successful,"failed_run_count":runs-successful,"last_ingestion_at":latest["finished_at"] if latest else None,"last_successful_ingestion_at":latest_success["finished_at"] if latest_success else None,"latest_run_status":"success" if latest and latest["success"] else "failed" if latest else None,"latest_run_rows_saved":latest["rows_saved"] if latest else 0,"latest_run_rows_failed":latest["rows_failed"] if latest else 0,"earliest_data_date":dates[0] if dates else None,"latest_data_date":dates[1] if dates else None}